	@ParameterizedTest(name = "actual native FILTER receipt after ORDER/TopK limit {0}")
	@ValueSource(longs = { 0L, 1L, 64L })
	void selectedNativeFilterReceiptRequiresTheOrderedTopKInputToComplete(long limit, TestReporter reporter)
			throws Exception {
		RecordingFilterStatistics statistics = new RecordingFilterStatistics();
		try (Fixture fixture = new Fixture(directory)) {
			QueryRoot ordinaryRoot = orderedTopKQuery(limit);
			var ordinary = new org.eclipse.rdf4j.query.algebra.evaluation.impl.DefaultEvaluationStrategy(
					fixture.source,
					(org.eclipse.rdf4j.query.algebra.evaluation.federation.FederatedServiceResolver) null);
			List<BindingSet> expected = drain(ordinary.precompile(ordinaryRoot), EmptyBindingSet.getInstance());

			var strategy = assertInstanceOf(LmdbNativeEvaluationStrategy.class,
					NativeQuerySourceAccess.evaluationStrategy(fixture.store, fixture.source, statistics));
			QueryRoot nativeRoot = assertInstanceOf(QueryRoot.class,
					strategy.optimize(orderedTopKQuery(limit), statistics, EmptyBindingSet.getInstance()));
			nativeRoot.setExecutionSummaryEnabled(true);
			Filter selectedFilter = firstFilter(nativeRoot);
			QueryEvaluationStep nativeStep = strategy.precompile(nativeRoot);
			String planned = nativeRoot.getStringMetricPlanned(LmdbNativeExplain.PHYSICAL_PLAN);
			assertNotNull(planned, "the normal compiler publishes its selected physical plan");
			assertTrue(planned.contains("RootPipeline(stages=[") && planned.contains("TopK(")
					&& planned.contains("limit=" + limit), planned);

			List<BindingSet> actual = drain(nativeStep, EmptyBindingSet.getInstance());
			String actualPath = nativeRoot.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
			reporter.publishEntry("actualSelectedNativeFilterReceipt", "limit=" + limit + "; planned=" + planned
					+ "; actualPath=" + actualPath + "; expected=" + summarizeFilterRows(expected)
					+ "; actual=" + summarizeFilterRows(actual) + "; receipts=" + statistics.receipts
					+ "; publicationStacks=" + statistics.publicationStacks);
			assertEquals(expected, actual, "the naturally selected ORDER/TopK result matches the ordinary source bag");
			if (limit == 0L) {
				assertEquals(List.of(), summarizeFilterRows(actual));
			} else if (limit == 1L) {
				assertEquals(List.of("urn:qualified-native:s:0|hit:0"), summarizeFilterRows(actual));
			} else {
				assertEquals(32, actual.size());
				assertQuarterBag(actual);
			}

			if (limit == 0L) {
				assertTrue(statistics.receipts.isEmpty(),
						"TopK limit zero admits no inner FILTER input and publishes no receipt");
			} else {
				assertEquals(1, statistics.receipts.size(), "the complete native FILTER publishes one receipt");
				FilterReceipt receipt = statistics.receipts.getFirst();
				assertSame(selectedFilter, receipt.filter(), "the receipt belongs to this query's actual FILTER");
				assertTrue(statistics.publicationStacks.getFirst()
						.stream()
						.anyMatch(frame -> frame.getClassName().equals(NativeFilterLease.Outcome.class.getName())
								&& frame.getMethodName().equals("publish")),
						"the receipt came from the actual native filter lease");
				assertTrue(
						statistics.publicationStacks.getFirst()
								.stream()
								.anyMatch(frame -> frame.getClassName().equals(NativeExecutionContext.class.getName())
										&& frame.getMethodName().equals("publishFilterOutcomesIfReady")),
						"the root owner published only after its resources and result borrowers settled");
				assertEquals(32L, receipt.observation().passedCount());
				assertEquals(96L, receipt.observation().filteredCount());
				assertTrue(receipt.observation().completed(), receipt.observation() + "; publicationStack="
						+ statistics.publicationStacks.getFirst());
			}
		}
	}

	@Test
	void cancellationBeforeTopKEmitsItsFirstRowVetoesACompletedFilterReceipt(TestReporter reporter)
			throws Exception {
		RecordingFilterStatistics statistics = new RecordingFilterStatistics();
		try (Fixture fixture = new Fixture(directory)) {
			QueryRoot ordinaryRoot = orderedTopKQuery(64L);
			var ordinary = new org.eclipse.rdf4j.query.algebra.evaluation.impl.DefaultEvaluationStrategy(
					fixture.source,
					(org.eclipse.rdf4j.query.algebra.evaluation.federation.FederatedServiceResolver) null);
			List<BindingSet> expected = drain(ordinary.precompile(ordinaryRoot), EmptyBindingSet.getInstance());
			assertQuarterBag(expected);

			var strategy = assertInstanceOf(LmdbNativeEvaluationStrategy.class,
					NativeQuerySourceAccess.evaluationStrategy(fixture.store, fixture.source, statistics));
			QueryRoot nativeRoot = assertInstanceOf(QueryRoot.class,
					strategy.optimize(orderedTopKQuery(64L), statistics, EmptyBindingSet.getInstance()));
			nativeRoot.setExecutionSummaryEnabled(true);
			Filter selectedFilter = firstFilter(nativeRoot);
			QueryEvaluationStep nativeStep = strategy.precompile(nativeRoot);
			String planned = nativeRoot.getStringMetricPlanned(LmdbNativeExplain.PHYSICAL_PLAN);
			assertNotNull(planned);
			assertTrue(planned.contains("RootPipeline(stages=[") && planned.contains("TopK(")
					&& planned.contains("limit=64"), planned);

			boolean accepted;
			List<BindingSet> emittedAfterCancellation = new java.util.ArrayList<>();
			try (var rows = nativeStep.evaluate(EmptyBindingSet.getInstance())) {
				assertNotNull(NativeExecutionContextCarrier.contextOf(rows),
						"the public root result retains its real native execution context");
				assertTrue(rows.hasNext(), "the actual TopK fully stages the real FILTER input and has a pending row");
				accepted = assertInstanceOf(org.eclipse.rdf4j.common.iteration.CooperativeCancellation.class,
						rows).requestCancellation();
				while (rows.hasNext()) {
					emittedAfterCancellation.add(rows.next());
				}
			}

			reporter.publishEntry("cancelledBeforeTopKOutput", "accepted=" + accepted + "; emittedAfterCancellation="
					+ summarizeFilterRows(emittedAfterCancellation) + "; plan=" + planned + "; receipts="
					+ statistics.receipts + "; stacks=" + statistics.publicationStacks);
			org.junit.jupiter.api.Assertions.assertAll("accepted cancellation before TopK output",
					() -> assertTrue(accepted, "the still-open root result accepts cancellation before its first row"),
					() -> assertEquals(List.of(), emittedAfterCancellation,
							"accepted cancellation before next() emits no buffered TopK rows"),
					() -> assertTrue(
							statistics.receipts.stream().noneMatch(receipt -> receipt.observation().completed()),
							"cancellation cannot publish complete selected-filter evidence"),
					() -> {
						if (!statistics.receipts.isEmpty()) {
							FilterReceipt receipt = statistics.receipts.getFirst();
							org.junit.jupiter.api.Assertions.assertAll("real native FILTER receipt",
									() -> assertEquals(1, statistics.receipts.size()),
									() -> assertSame(selectedFilter, receipt.filter()),
									() -> assertEquals(32L, receipt.observation().passedCount()),
									() -> assertEquals(96L, receipt.observation().filteredCount()),
									() -> assertTrue(statistics.publicationStacks.getFirst()
											.stream()
											.anyMatch(frame -> frame.getClassName()
													.equals(NativeFilterLease.Outcome.class.getName())
													&& frame.getMethodName().equals("publish"))),
									() -> assertTrue(statistics.publicationStacks.getFirst()
											.stream()
											.anyMatch(frame -> frame.getClassName()
													.equals(NativeExecutionContext.class.getName())
													&& frame.getMethodName().equals("publishFilterOutcomesIfReady"))));
						}
					});
		}
	}

