	private static QueryRoot orderedTopKQuery(long limit) {
		TupleExpr parsed = parse();
		TupleExpr body = parsed instanceof QueryRoot queryRoot ? queryRoot.getArg() : parsed;
		Slice inner = new Slice(body.clone(), 0L, 64L);
		Order order = new Order(inner, new OrderElem(Var.of("s")));
		return new QueryRoot(new Slice(order, 0L, limit));
	}

	private static QueryRoot fullOrderedFilterQuery() {
		TupleExpr parsed = parse();
		TupleExpr body = parsed instanceof QueryRoot queryRoot ? queryRoot.getArg() : parsed;
		Slice inner = new Slice(body.clone(), 0L, 64L);
		return new QueryRoot(new Order(inner, new OrderElem(Var.of("s"))));
	}

	private static List<String> summarizeFilterRows(List<BindingSet> rows) {
		return rows.stream()
				.map(row -> row.getValue("s").stringValue() + "|" + row.getValue("v").stringValue())
				.toList();
	}

