	@Test
	void oneCompiledNativeStepKeepsConcurrentQualifiedExecutionsSeparate() throws Exception {
		try (Fixture fixture = new Fixture(directory); var workers = Executors.newVirtualThreadPerTaskExecutor()) {
			Compiled compiled = fixture.compile(false);
			CountDownLatch opened = new CountDownLatch(2);
			CountDownLatch release = new CountDownLatch(1);
			java.util.concurrent.Callable<Integer> run = () -> {
				try (var rows = compiled.step().evaluate(EmptyBindingSet.getInstance())) {
					opened.countDown();
					assertTrue(release.await(10, TimeUnit.SECONDS));
					int count = 0;
					while (rows.hasNext()) {
						rows.next();
						count++;
					}
					return count;
				}
			};
			var first = workers.submit(run);
			var second = workers.submit(run);
			try {
				assertTrue(opened.await(10, TimeUnit.SECONDS));
			} finally {
				release.countDown();
			}
			assertEquals(32, first.get(10, TimeUnit.SECONDS).intValue());
			assertEquals(32, second.get(10, TimeUnit.SECONDS).intValue());
			fixture.assertLearned(compiled.filter(), 2L * INPUTS);
		}
	}

