	enum Authority {
		STALE,
		CLOSED,
		FOREIGN_SOURCE
	}

	@ParameterizedTest
	@EnumSource(Authority.class)
	void invalidSourceCannotPublishQualifiedFeedback(Authority authority) throws Exception {
		try (Fixture fixture = new Fixture(directory)) {
			if (authority == Authority.FOREIGN_SOURCE) {
				try (Fixture foreign = new Fixture(new File(directory, "foreign"))) {
					var strategy = (LmdbNativeEvaluationStrategy) NativeQuerySourceAccess.evaluationStrategy(
							fixture.store, foreign.source, fixture.statistics);
					TupleExpr root = strategy.optimize(parse(), fixture.statistics, EmptyBindingSet.getInstance());
					assertEquals(32, drain(strategy.precompile(root), EmptyBindingSet.getInstance()).size());
					fixture.assertNoLearning();
					foreign.assertNoLearning();
				}
				return;
			}
			Compiled compiled = fixture.compile(false);
			if (authority == Authority.CLOSED) {
				fixture.dataset.close();
				assertThrows(RuntimeException.class, () -> drain(compiled.step(), EmptyBindingSet.getInstance()));
			} else {
				try (var connection = fixture.repository.getConnection()) {
					var vf = fixture.store.getValueFactory();
					connection.add(vf.createIRI("urn:qualified-native:mutation"),
							vf.createIRI("urn:qualified-native:other"), vf.createLiteral(true));
				}
				assertEquals(32, drain(compiled.step(), EmptyBindingSet.getInstance()).size(),
						"the old snapshot still returns its own rows");
			}
			fixture.assertNoLearning();
		}
	}

