	@Test
	void boundedMemoProbeCannotPublishOrCancelTheSelectedQualifiedProducer() throws Exception {
		try (Fixture fixture = new Fixture(directory)) {
			Physical physical = fixture.physical();
			AtomicInteger opens = new AtomicInteger();
			fixture.block(physical, row -> {
				NativeSubqueryPlan memo = memo(physical, opens);
				NativeFilterLease trial = new NativeFilterLease();
				var attempts = LmdbNativeProbeDeadline.ownAttemptStates();
				Throwable signal = null;
				try (var deadline = LmdbNativeProbeDeadline.enter(LmdbNativeProbeDeadline.trippableOnly());
						RowCursor cursor = trial.borrow(memo).open(row.fork())) {
					assertTrue(cursor.next());
					signal = LmdbNativeProbeDeadline.capacityExhausted();
					assertSame(signal, assertThrows(RuntimeException.class, cursor::next));
				} finally {
					trial.discard();
					assertSame(signal, attempts.settled(signal, false));
				}
				assertFalse(row.cancellation.cancellationPublished());
				NativeFilterLease winner = new NativeFilterLease();
				assertEquals(32, drainPlan(winner.borrow(memo), row, false));
				assertEquals(32, drainPlan(winner.borrow(memo), row, false));
				winner.commit();
			});
			assertEquals(2, opens.get(), "probe and selected producer are isolated; selected replay is computed once");
			fixture.assertLearned(physical.filter(), INPUTS);
		}
	}

