	@ParameterizedTest
	@org.junit.jupiter.params.provider.EnumSource(SyntheticOrigin.class)
	void syntheticValuesFoldHonorsItsActuallyPreparedOriginContract(SyntheticOrigin originKind) throws Exception {
		try (Fixture fixture = new Fixture(new File(directory, "local"), originKind != SyntheticOrigin.LEGACY_ONLY);
				Fixture foreign = new Fixture(new File(directory, "foreign"),
						originKind != SyntheticOrigin.LEGACY_ONLY)) {
			var vf = fixture.store.getValueFactory();
			TupleExpr data = new org.eclipse.rdf4j.query.algebra.Extension(
					new org.eclipse.rdf4j.query.algebra.StatementPattern(Var.of("s"),
							Var.of("predicate", vf.createIRI("urn:qualified-native:p"), true, true), Var.of("raw")),
					new org.eclipse.rdf4j.query.algebra.ExtensionElem(Var.of("raw"), "v"));
			BindingSetAssignment values = new BindingSetAssignment();
			ListBindingSet target = new ListBindingSet(List.of("target"), List.of(vf.createLiteral("hit:0")));
			values.setDeclaredBindingNames(Set.of("target"));
			values.setBindingSets(List.of(target));
			Filter origin = new Filter(new Join(data, values), new Compare(Var.of("v"), Var.of("target")));
			origin.setConditionBindingScope(Filter.ConditionBindingScope.ALL);
			QueryRoot root = new QueryRoot(new org.eclipse.rdf4j.query.algebra.Distinct(
					new org.eclipse.rdf4j.query.algebra.Projection(origin,
							new org.eclipse.rdf4j.query.algebra.ProjectionElemList(
									new org.eclipse.rdf4j.query.algebra.ProjectionElem("s"),
									new org.eclipse.rdf4j.query.algebra.ProjectionElem("v")),
							false)));
			PlanningGraphDomains.capture(root, PlanningGraphDomain.defaultGraph());
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((org.eclipse.rdf4j.query.Dataset) null);
			org.eclipse.rdf4j.query.algebra.feedback.RuntimeFeedbackContract prepared = null;
			if (originKind != SyntheticOrigin.NO_CONTRACT && originKind != SyntheticOrigin.LEGACY_ONLY) {
				Filter foreignOrigin = origin.clone();
				fixture.strategy.genericPrecompile(origin, context);
				prepared = origin.getRuntimeFeedbackContract();
				assertNotNull(prepared, "ordinary LMDB preparation supplies the real origin descriptor");
				assertTrue(
						prepared.admits(org.eclipse.rdf4j.query.algebra.feedback.RuntimeFeedbackContract.ADMIT_FILTER));
				if (originKind == SyntheticOrigin.FOREIGN_SAME_EPOCH) {
					foreign.strategy.genericPrecompile(foreignOrigin,
							new QueryEvaluationContext.Minimal((org.eclipse.rdf4j.query.Dataset) null));
					var foreignPrepared = foreignOrigin.getRuntimeFeedbackContract();
					assertNotNull(foreignPrepared, "the foreign destination is also genuinely prepared");
					assertEquals(prepared.dataEpoch(), foreignPrepared.dataEpoch());
					assertEquals(prepared.catalogEpoch(), foreignPrepared.catalogEpoch());
					assertNotEquals(prepared.descriptor(), foreignPrepared.descriptor(),
							"owner/read identity must differ");
					origin.setRuntimeFeedbackContract(foreignPrepared);
				} else if (originKind == SyntheticOrigin.DENIED) {
					origin.setRuntimeFeedbackContract(withoutFilterAdmission(prepared));
					assertSame(prepared.descriptor(), origin.getRuntimeFeedbackContract().descriptor());
				} else if (originKind == SyntheticOrigin.UNKNOWN_DESCRIPTOR) {
					// This is intentionally untrusted public-API input, never fabricated positive authority.
					origin.setRuntimeFeedbackContract(prepared.withDescriptor(
							new org.eclipse.rdf4j.query.algebra.feedback.RuntimeFeedbackDescriptor() {
							}));
				} else if (originKind == SyntheticOrigin.UNKNOWN_GRAPH) {
					PlanningGraphDomains.capture(origin, PlanningGraphDomain.unknown());
					assertSame(prepared, origin.getRuntimeFeedbackContract());
				}
			} else {
				assertEquals(null, origin.getRuntimeFeedbackContract());
			}
			var expectedContract = origin.getRuntimeFeedbackContract();
			var planner = new LmdbNativeAggregatePlanner(context, fixture.strategy,
					(NativeLmdbQuerySource) fixture.dataset);
			// A computed alias cannot be reverse-probed on its source pattern, so the real compiler retains a
			// residual VALUES membership filter rather than eliding the very observation under test.
			QueryEvaluationStep step = planner.compileRowRoot(root);
			NativeRowsStep nativeRows = assertInstanceOf(NativeRowsStep.class, step,
					"normal SELECT DISTINCT projection compilation must admit the real native row root");
			assertTrue(nativeRows.distinct,
					"the ordinary DISTINCT supplies the compiler's duplicate-insensitive contract");
			FilterPlan gate = foldedMembershipGate(nativeRows.arg);
			RecordingNativeBooleanFilter recording = assertInstanceOf(RecordingNativeBooleanFilter.class, gate.filter);
			assertInstanceOf(ValueSetFilter.class, recording.delegate);
			assertNotSame(origin, recording.filter, "this is the actual synthetic population surface");
			assertSame(expectedContract, origin.getRuntimeFeedbackContract(),
					"native preparation cannot replace origin authority");
			var legacyBefore = NativeQuerySourceAccess.legacyFilterEvidence(fixture.store, recording.filter);
			var foreignLegacyBefore = NativeQuerySourceAccess.legacyFilterEvidence(foreign.store, recording.filter);
			assertTrue(legacyBefore.revision() >= 0L, "the real optional legacy provider is published");
			assertEquals(-1L, legacyBefore.evidenceCount());
			List<BindingSet> actual = drain(step, EmptyBindingSet.getInstance());
			assertEquals(List.of("urn:qualified-native:s:0|hit:0"),
					actual.stream()
							.map(row -> row.getValue("s").stringValue() + "|" + row.getValue("v").stringValue())
							.sorted()
							.toList());
			foreign.assertNoLearning();
			assertEquals(foreignLegacyBefore,
					NativeQuerySourceAccess.legacyFilterEvidence(foreign.store, recording.filter));
			var legacyAfter = NativeQuerySourceAccess.legacyFilterEvidence(fixture.store, recording.filter);
			boolean inputAccepted = switch (originKind) {
			case NO_CONTRACT, PREPARED_LOCAL, LEGACY_ONLY -> true;
			case DENIED, UNKNOWN_DESCRIPTOR, UNKNOWN_GRAPH, FOREIGN_SAME_EPOCH -> false;
			};
			assertNotNull(recording.preparedOutcome, "LMDB preparation returns an admitted or denied outcome");
			assertEquals(inputAccepted, recording.preparedOutcome.acceptsInput(EmptyBindingSet.getInstance()),
					"prepared admission follows the origin's actual source and policy authority");
			fixture.assertNoLearning();
			assertEquals(legacyBefore, legacyAfter,
					"folded physical membership is not a complete logical filter input");
		}
	}

	@ParameterizedTest(name = "wholeFilter={0}, scalarTransport={1}, targets={2}")
	@org.junit.jupiter.params.provider.MethodSource("foldedMembershipPopulations")
	void foldedMembershipCannotTeachADifferentFutureJoinPopulation(boolean wholeFilter, boolean scalarTransport,
			List<String> targets) throws Exception {
		String property = "rdf4j.lmdb.factor.transport.enabled";
		String previous = System.getProperty(property);
		System.setProperty(property, scalarTransport ? "false" : "true");
		try (Fixture fixture = new Fixture(directory)) {
			var vf = fixture.store.getValueFactory();
			TupleExpr data = membershipData(vf);
			BindingSetAssignment values = membershipValues(vf, targets);
			Filter origin;
			TupleExpr trainingInput;
			if (wholeFilter) {
				origin = new Filter(new Join(data, values), new Compare(Var.of("v"), Var.of("target")));
				trainingInput = origin;
			} else {
				origin = new Filter(values, new Compare(Var.of("v"), Var.of("target")));
				origin.setRequiredInputBindingNames(Set.of("v"));
				trainingInput = new Join(data, origin);
			}
			origin.setConditionBindingScope(Filter.ConditionBindingScope.ALL);
			QueryRoot trainingRoot = membershipRoot(trainingInput, true);
			trainingRoot.setExecutionSummaryEnabled(true);
			PlanningGraphDomains.capture(trainingRoot, PlanningGraphDomain.defaultGraph());

			// The independent future query owns a real join population. It is never evaluated before lookup.
			TupleExpr futureInput = wholeFilter
					? new Join(new Join(data.clone(), values.clone()), new Join(data.clone(), values.clone()))
					: new Join(data.clone(), values.clone());
			Filter futureFilter = new Filter(futureInput, new Compare(Var.of("v"), Var.of("target")));
			futureFilter.setConditionBindingScope(Filter.ConditionBindingScope.ALL);
			QueryRoot futureRoot = membershipRoot(futureFilter, false);
			PlanningGraphDomains.capture(futureRoot, PlanningGraphDomain.defaultGraph());
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((org.eclipse.rdf4j.query.Dataset) null);
			fixture.strategy.genericPrecompile(futureRoot, context);
			assertEquals(-1L,
					NativeQuerySourceAccess.legacyFilterEvidence(fixture.store, futureFilter).evidenceCount());

			// Enter actual common preparation, including immutable VALUES capture, before inspecting its compiler
			// shape.
			QueryEvaluationStep prepared = fixture.strategy.precompile(trainingRoot);
			var planner = new LmdbNativeAggregatePlanner(context, fixture.strategy,
					(NativeLmdbQuerySource) fixture.dataset);
			NativeRowsStep physical = assertInstanceOf(NativeRowsStep.class, planner.compileRowRoot(trainingRoot));
			FilterPlan gate = foldedMembershipGate(physical.arg);
			RecordingNativeBooleanFilter recording = assertInstanceOf(RecordingNativeBooleanFilter.class, gate.filter);
			assertInstanceOf(ValueSetFilter.class, recording.delegate,
					"the ordinary compiler must retain real membership execution");
			List<String> expectedDistinct = targets.stream()
					.distinct()
					.map(value -> membershipRow(value))
					.sorted()
					.toList();
			assertEquals(expectedDistinct, membershipRows(drain(prepared, EmptyBindingSet.getInstance())));
			assertEquals("lmdb-native",
					trainingRoot.getStringMetricPlanned(TelemetryMetricNames.PLANNED_EXECUTION_ENGINE));
			assertNotEquals("genericHostedRoot",
					trainingRoot.getStringMetricPlanned(TelemetryMetricNames.PLANNED_EXECUTION_KIND));
			assertNotNull(trainingRoot.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH));

			java.util.Map<String, Long> multiplicities = targets.stream()
					.collect(java.util.stream.Collectors.groupingBy(
							java.util.function.Function.identity(), java.util.stream.Collectors.counting()));
			long futureCopies = multiplicities.values()
					.stream()
					.mapToLong(count -> wholeFilter ? count * count : count)
					.sum();
			long futureInputRows = INPUTS * futureCopies;
			long membershipInputRows = INPUTS;
			if (futureInputRows != membershipInputRows || futureCopies != expectedDistinct.size()) {
				var beforeFutureExecution = fixture.statistics.estimateFilterPass(futureFilter);
				assertFalse(isLearned(beforeFutureExecution),
						"membership over " + membershipInputRows + " rows cannot train a different "
								+ futureInputRows + "-row join; " + physical.nativePhysicalPlan());
				assertEquals(-1L,
						NativeQuerySourceAccess.legacyFilterEvidence(fixture.store, futureFilter).evidenceCount(),
						"the legacy exact/generalized cells cannot borrow a different population either");
			}
			if (wholeFilter && targets.size() != 1) {
				Filter originalPopulation = new Filter(new Join(data.clone(), values.clone()),
						new Compare(Var.of("v"), Var.of("target")));
				originalPopulation.setConditionBindingScope(Filter.ConditionBindingScope.ALL);
				QueryRoot originalRoot = membershipRoot(originalPopulation, false);
				PlanningGraphDomains.capture(originalRoot, PlanningGraphDomain.defaultGraph());
				fixture.strategy.genericPrecompile(originalRoot, context);
				assertFalse(isLearned(fixture.statistics.estimateFilterPass(originalPopulation)),
						"removing the duplicate diagnostic join cannot authorize the still-different original VALUES join");
				assertEquals(-1L, NativeQuerySourceAccess.legacyFilterEvidence(fixture.store, originalPopulation)
						.evidenceCount());
			}
			// Standard evaluation independently checks the actual future multiset only after the non-reuse assertions.
			var reference = new org.eclipse.rdf4j.query.algebra.evaluation.impl.DefaultEvaluationStrategy(
					fixture.source,
					(org.eclipse.rdf4j.query.algebra.evaluation.federation.FederatedServiceResolver) null);
			List<String> expectedFuture = new java.util.ArrayList<>();
			multiplicities.forEach((value, count) -> {
				for (long i = 0, copies = wholeFilter ? count * count : count; i < copies; i++) {
					expectedFuture.add(membershipRow(value));
				}
			});
			expectedFuture.sort(String::compareTo);
			assertEquals(expectedFuture,
					membershipRows(drain(reference.precompile(futureRoot), EmptyBindingSet.getInstance())));
		} finally {
			if (previous == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, previous);
			}
		}
	}

	private static FilterPlan foldedMembershipGate(SlotPlan plan) {
		NativeValuesFoldPlan guarded = assertInstanceOf(NativeValuesFoldPlan.class, plan,
				"the actual native fold retains its caller-sensitive original operand");
		assertEquals(List.of("target"), List.of(guarded.inputNames));
		assertTrue((guarded.original.producedMask() & guarded.inputMask) != 0L,
				"the retained input can supply the eliminated VALUES target");
		assertEquals(0L, SlotPlan.assuredMask(guarded) & guarded.inputMask,
				"the fast branch cannot promise the eliminated target as an output");
		return assertInstanceOf(FilterPlan.class, guarded.folded,
				"the real selected native branch retains its residual membership gate");
	}

	private static java.util.stream.Stream<org.junit.jupiter.params.provider.Arguments> foldedMembershipPopulations() {
		return java.util.stream.Stream.of(false, true)
				.flatMap(whole -> java.util.stream.Stream.of(false, true)
						.flatMap(scalar -> java.util.stream.Stream.of(List.of("hit:0"), List.of("hit:0", "miss:1"),
								List.of("hit:0", "hit:0"), List.of("hit:0", "hit:0", "miss:1"),
								List.of("miss:1", "hit:0"))
								.map(targets -> org.junit.jupiter.params.provider.Arguments.of(whole, scalar,
										targets))));
	}

